import{_ as p,a0 as o,w as l,s as r,ao as d,I as n,x as s,a1 as i,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"awk 系列：如何使用 awk 按模式篩選文本或字符串 | LCTT x X-CMD","titleTemplate":false,"description":"awk 系列：如何使用 awk 按模式篩選文本或字符串 | LCTT (awk) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"awk 系列：如何使用 awk 按模式篩選文本或字符串 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"awk 系列：如何使用 awk 按模式篩選文本或字符串 | LCTT (awk) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"awk/Part 3 - How to Use Awk to Filter Text or Strings Using Pattern Specific Actions","title":"awk 系列：如何使用 awk 按模式篩選文本或字符串","tag":"awk","desc":""},"relativePath":"awk/Part 3 - How to Use Awk to Filter Text or Strings Using Pattern Specific Actions.md","filePath":"[post].md"}'),k={name:"awk/Part 3 - How to Use Awk to Filter Text or Strings Using Pattern Specific Actions.md"};function w(g,t,c,u,h,m){const a=o("Link");return l(),r("div",null,[t[13]||(t[13]=d(`<h1 id="awk-系列-如何使用-awk-按模式篩選文本或字符串" tabindex="-1">awk 系列：如何使用 awk 按模式篩選文本或字符串 <a class="header-anchor" href="#awk-系列-如何使用-awk-按模式篩選文本或字符串" aria-label="Permalink to “awk 系列：如何使用 awk 按模式篩選文本或字符串”">​</a></h1><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Use-Awk-to-Filter-Text-or-Strings-Using-Pattern.png" alt=""></p><p>作為 awk 命令系列的第三部分，這次我們將看一看如何基於用户定義的特定模式來篩選文本或字符串。</p><p>在篩選文本時，有時你可能想根據某個給定的條件或使用一個可被匹配的特定模式，去標記某個文件或數行字符串中的某幾行。使用 awk 來完成這個任務是非常容易的，這也正是 awk 中可能對你有所幫助的幾個功能之一。</p><p>讓我們看一看下面這個例子，比方説你有一個寫有你想要購買的食物的購物清單，其名稱為 food_prices.list，它所含有的食物名稱及相應的價格如下所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ cat food_prices.list </span></span>
<span class="line"><span>No	Item_Name		Quantity	Price</span></span>
<span class="line"><span>1	Mangoes			   10		$2.45</span></span>
<span class="line"><span>2	Apples			   20		$1.50</span></span>
<span class="line"><span>3	Bananas			   5		$0.90</span></span>
<span class="line"><span>4	Pineapples		   10		$3.46</span></span>
<span class="line"><span>5	Oranges			   10		$0.78</span></span>
<span class="line"><span>6	Tomatoes		   5		$0.55</span></span>
<span class="line"><span>7	Onions			   5        $0.45</span></span></code></pre></div><p>然後，你想使用一個 <code>(*)</code> 符號去標記那些單價大於 $2 的食物，那麼你可以通過運行下面的命令來達到此目的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;/ *\\$[2-9]\\.[0-9][0-9] */ { print $1, $2, $3, $4, &quot;*&quot; ; } / *\\$[0-1]\\.[0-9][0-9] */ { print ; }&#39; food_prices.list</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Filter-and-Print-Text-Using-Awk.gif" alt=""></p><p><em>打印出單價大於 $2 的項目</em></p><p>從上面的輸出你可以看到在含有 芒果（mangoes） 和菠蘿（pineapples）的那行末尾都已經有了一個 <code>(*)</code> 標記。假如你檢查它們的單價，你可以看到它們的單價的確超過了 $2 。</p><p>在這個例子中，我們已經使用了兩個模式：</p><ul><li>第一個模式: <code>/ *\\$[2-9]\\.[0-9][0-9] */</code> 將會得到那些含有食物單價大於 $2 的行，</li><li>第二個模式: <code>/*\\$[0-1]\\.[0-9][0-9] */</code> 將查找那些食物單價小於 $2 的那些行。</li></ul><p>上面的命令具體做了什麼呢？這個文件有四個字段，當模式一匹配到含有食物單價大於 $2 的行時，它便會輸出所有的四個字段並在該行末尾加上一個 <code>(*)</code> 符號來作為標記。</p><p>第二個模式只是簡單地輸出其他含有食物單價小於 $2 的行，按照它們出現在輸入文件 food_prices.list 中的樣子。</p><p>這樣你就可以使用模式來篩選出那些價格超過 $2 的食物項目，儘管上面的輸出還有些問題，帶有 <code>(*)</code> 符號的那些行並沒有像其他行那樣被格式化輸出，這使得輸出顯得不夠清晰。</p><p>我們在 awk 系列的第二部分中也看到了同樣的問題，但我們可以使用下面的兩種方式來解決：</p><p>1、可以像下面這樣使用 printf 命令，但這樣使用又長又無聊：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;/ *\\$[2-9]\\.[0-9][0-9] */ { printf &quot;%-10s %-10s %-10s %-10s\\n&quot;, $1, $2, $3, $4 &quot;*&quot; ; } / *\\$[0-1]\\.[0-9][0-9] */ { printf &quot;%-10s %-10s %-10s %-10s\\n&quot;, $1, $2, $3, $4; }&#39; food_prices.list</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Filter-and-Print-Items-Using-Awk-and-Printf.gif" alt=""></p><p><em>使用 Awk 和 Printf 來篩選和輸出項目</em></p><p>2、 使用 <code>$0</code> 字段。Awk 使用變量 <strong>0</strong> 來存儲整個輸入行。對於上面的問題，這種方式非常方便，並且它還簡單、快速：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ awk &#39;/ *\\$[2-9]\\.[0-9][0-9] */ { print $0 &quot;*&quot; ; } / *\\$[0-1]\\.[0-9][0-9] */ { print ; }&#39; food_prices.list</span></span></code></pre></div><p><img src="http://www.tecmint.com/wp-content/uploads/2016/04/Filter-and-Print-Items-Using-Awk-and-Variable.gif" alt=""></p><p><em>使用 Awk 和變量來篩選和輸出項目</em></p><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>這就是全部內容了，使用 awk 命令你便可以通過幾種簡單的方法去利用模式匹配來篩選文本，幫助你在一個文件中對文本或字符串的某些行做標記。</p><p>希望這篇文章對你有所幫助。記得閲讀這個系列的下一部分，我們將關注在 awk 工具中使用比較運算符。</p><hr>`,29)),n("p",null,[t[1]||(t[1]=s("via: ",-1)),i(a,{href:"http://www.tecmint.com/awk-filter-text-or-string-using-patterns/"},{default:e(()=>[...t[0]||(t[0]=[s("http://www.tecmint.com/awk-filter-text-or-string-using-patterns/",-1)])]),_:1})]),n("p",null,[t[5]||(t[5]=s("作者：",-1)),i(a,{href:"http://www.tecmint.com/author/aaronkili/"},{default:e(()=>[...t[2]||(t[2]=[s("Aaron Kili",-1)])]),_:1}),t[6]||(t[6]=s(" 譯者：",-1)),i(a,{href:"https://github.com/FSSlc"},{default:e(()=>[...t[3]||(t[3]=[s("FSSlc",-1)])]),_:1}),t[7]||(t[7]=s(" 校對：",-1)),i(a,{href:"https://github.com/wxy"},{default:e(()=>[...t[4]||(t[4]=[s("wxy",-1)])]),_:1})]),n("p",null,[t[10]||(t[10]=s("本文由 ",-1)),i(a,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[8]||(t[8]=[s("LCTT",-1)])]),_:1}),t[11]||(t[11]=s(" 原創編譯，",-1)),i(a,{href:"https://linux.cn/"},{default:e(()=>[...t[9]||(t[9]=[s("Linux中國",-1)])]),_:1}),t[12]||(t[12]=s(" 榮譽推出",-1))])])}const T=p(k,[["render",w]]);export{b as __pageData,T as default};
